[3802] = "%s(으)로 집계되는 그룹원 수",
-- 658bb8cf English: ranged
-- Context: Weapon slot in summaries: the ranged weapon (lowercase).
[3803] = "원거리",
-- 80c798fc English: type %s
-- Context: Part of the instance summary; %s is the instance type, e.g. 'type Dungeon'.
-- %s #1: %s #1: the instance type, e.g. "Dungeon", "Raid" or "Battleground"
[3804] = "유형 %s",
-- 78aee9bb English: difficulty %s
-- Context: Part of the instance summary; %s is the difficulty name, e.g. 'difficulty Heroic'.
-- %s #1: %s #1: the difficulty name, e.g. "Heroic"
[3805] = "난이도 %s",
-- 5e900d17 English: ID %s
-- Context: Part of the instance summary; %s is the instance ID number, e.g. 'ID 33'.
-- %s #1: %s #1: the instance ID, e.g. 409
[3806] = "인스턴스 ID %s",
-- 08c231ad English: you {{!are|are not}} in an instance (%s)
-- %s #1: %s #1: the instance details separated by commas, e.g. "type Raid, difficulty Heroic, ID 409"
[3807] = "인스턴스(%s)에 {{!있음|있지 않음}}",
-- 364397ab English: Any difficulty
-- Context: Option at the top of the instance difficulty dropdown: do not restrict by difficulty.
[3808] = "모든 난이도",
-- bd945e03 English: None (use the item above)
[3809] = "없음 (위의 아이템 사용)",
-- 02de34c4 English: A number of players, or a percent of the whole group when the box is ticked.
--     You are always part of the group and of every count you fit.
[3810] = "플레이어 수이며, 상자를 선택하면 전체 그룹에 대한 비율입니다. 본인은 항상 그룹의 일원이며 해당하는 모든 집계에 포함됩니다.",
-- d758a0ce English: Matches while you are in the chosen state. Mounted, swimming (at the surface or
--     under water), flying, falling and in a rested area (an inn or a capital city) describe where
--     you are and how you move. Dead means you have died and not yet released your spirit; Ghost
--     means you have released it. A state the game cannot report right now is unavailable rather
--     than false. Being stealthed, outdoors or in control of your character have their own
--     conditions, and Is Dead or Ghost tests any unit.
[3811] = "선택한 상태에 있는 동안 일치합니다. 탈것 탑승 중, 수영 중(수면 또는 물속), 비행 중, 낙하 중, 휴식 지역(여관 또는 수도)은 현재 위치와 이동 방식을 나타냅니다. 사망은 죽었지만 아직 영혼을 풀어주지 않은 상태이고, 유령은 영혼을 풀어준 상태입니다. 게임이 지금 알려 줄 수 없는 상태는 거짓이 아니라 사용할 수 없음으로 처리됩니다. 은신 상태, 실외, 캐릭터 조작 가능 여부에는 각각의 조건이 있으며, 죽었거나 유령 상태인지는 모든 유닛을 확인할 수 있습니다.",
-- b4a1a7b5 English: Counts the players in your party or raid, always including you: the whole
--     group, the members holding an assigned role (Tank, Healer or damage dealer) or the members
--     who are dead or ghosts. Tick the box to compare a percent of the whole group instead of a
--     number of players, for example more than 50 percent dead. Alone, the group is 1 player. A
--     member with no assigned role is not counted under any role. A member the game cannot report
--     makes the count unavailable rather than too low.
[3812] = "파티 또는 공격대의 플레이어 수를 항상 본인을 포함해 셉니다. 전체 그룹, 지정된 역할(방어 전담, 치유 전담, 공격 전담)을 가진 그룹원, 또는 죽었거나 유령 상태인 그룹원을 셀 수 있습니다. 상자를 선택하면 플레이어 수 대신 전체 그룹에 대한 비율로 비교합니다(예: 50% 넘게 사망). 혼자일 때 그룹은 1명입니다. 지정된 역할이 없는 그룹원은 어떤 역할로도 집계되지 않습니다. 게임이 알려 줄 수 없는 그룹원이 있으면 값이 낮게 나오는 대신 집계를 사용할 수 없음으로 처리합니다.",
-- e1167554 English: Balance Druid Eclipse. Choose the measure first. Direction matches while the
--     Eclipse bar is heading toward a Solar or a Lunar Eclipse. Energy compares the bar itself,
--     from -100 (a full Lunar Eclipse) to 100 (a full Solar Eclipse), using the operator and value.
--     Only the fields of the chosen measure are used.
[3813] = "조화 드루이드의 일식/월식입니다. 먼저 측정 항목을 고르세요. 방향은 일식/월식 막대가 일식 또는 월식 쪽으로 향하는 동안 일치합니다. 에너지는 막대 자체를 -100(완전한 월식)부터 100(완전한 일식)까지의 값으로 연산자와 값에 따라 비교합니다. 선택한 측정 항목의 필드만 사용됩니다.",
-- 66261852 English: Instance Difficulty and Instance ID are optional. Every part you set must
--     match, for example a Dungeon on Heroic difficulty, or one particular instance by its ID (the
--     editor shows the ID of the instance you are in). The ID does not change with the game's
--     language the way a zone name does.
[3814] = "인스턴스 난이도와 인스턴스 ID는 선택 사항입니다. 설정한 항목은 모두 일치해야 합니다(예: 영웅 난이도의 던전, 또는 ID로 지정한 특정 인스턴스. 편집기에 현재 있는 인스턴스의 ID가 표시됩니다). ID는 지역 이름과 달리 게임 언어에 따라 바뀌지 않습니다.",
-- 347c420f English: Choose a trinket slot to read whatever is equipped there, so one rotation works
--     for every trinket; the item above is then ignored. An empty slot is false, and a trinket with
--     no on-use effect is unavailable.
[3815] = "장신구 칸을 고르면 그 칸에 장착된 것이 무엇이든 읽으므로 하나의 로테이션이 모든 장신구에 쓰입니다. 이때 위의 아이템은 무시됩니다. 빈 칸은 거짓이며, 사용 효과가 없는 장신구는 사용할 수 없음으로 처리됩니다.",
-- 41e5c95c English: Measure your Auto Shot or wand shot instead of a melee weapon. Choose Off Hand
--     or Ranged, not both. The time remaining needs the combat log, so it works on Classic Era,
--     Burning Crusade and Mists of Pandaria but not on Retail or Forever.
[3816] = "근접 무기 대신 자동 사격이나 지팡이 사격을 측정합니다. 보조장비와 원거리 중 하나만 선택하세요. 남은 시간에는 전투 기록이 필요하므로 Classic Era, 불타는 성전, 판다리아의 안개에서는 작동하지만 리테일과 Forever에서는 작동하지 않습니다.",
-- a8b3d1b8 English: Number of %s in combat within %s yards
-- %s #1: %s #1: either "enemies" or "allies", e.g. "enemies"
-- %s #2: %s #2: the distance in yards, e.g. 10
[3817] = "전투 중인 %s의 %s미터 이내 수",
-- e7ccbb83 English: Count only units that are in combat. For enemies that is the ones fighting
--     right now, not every enemy whose nameplate is visible. A unit whose combat state the game
--     will not report makes the count unavailable.
[3818] = "전투 중인 유닛만 셉니다. 적의 경우 이름표가 보이는 모든 적이 아니라 지금 싸우고 있는 적입니다. 게임이 전투 상태를 알려 주지 않는 유닛이 있으면 집계를 사용할 수 없음으로 처리합니다.",
-- 42f0cd37 English: Any mark
-- Context: Choice in the mark dropdown of the Raid Mark condition: the unit carries any raid
--     marker.
[4067] = "아무 징표",
-- 1bc1f1c6 English: No mark
-- Context: Choice in the mark dropdown of the Raid Mark condition: the unit carries no raid marker.
[4068] = "징표 없음",
-- 36baf150 English: One of these marks
[4069] = "이 징표 중 하나",
-- 582de115 English: %s {{!have|do not have}} a raid mark
-- Context: Sentence the Raid Mark condition prints. Used when the unit is the player ("you"). The
--     {{!positive|negated}} part is the wording for the condition and for its NOT form.
-- %s #1: the unit phrase, e.g. "your target"
[4070] = "%s {{!공격대 징표 있음|공격대 징표 없음}}",
-- 472cb18e English: %s {{!has|does not have}} a raid mark
-- Context: Sentence the Raid Mark condition prints. Used when the unit is anyone else (third
--     person, "has"). The {{!positive|negated}} part is the wording for the condition and for its
--     NOT form.
-- %s #1: the unit phrase, e.g. "your target"
[4071] = "%s {{!공격대 징표 있음|공격대 징표 없음}}",
-- 4235af62 English: %s {{!have no|have a}} raid mark
-- Context: Sentence the Raid Mark condition prints. Used when the unit is the player ("you"). The
--     {{!positive|negated}} part is the wording for the condition and for its NOT form.
-- %s #1: the unit phrase, e.g. "your target"
[4072] = "%s {{!공격대 징표 없음|공격대 징표 있음}}",
-- 4f17a484 English: %s {{!has no|has a}} raid mark
-- Context: Sentence the Raid Mark condition prints. Used when the unit is anyone else (third
--     person, "has"). The {{!positive|negated}} part is the wording for the condition and for its
--     NOT form.
-- %s #1: the unit phrase, e.g. "your target"
[4073] = "%s {{!공격대 징표 없음|공격대 징표 있음}}",
-- a8bca387 English: %s {{!have|do not have}} one of these marks: %s
-- Context: Sentence the Raid Mark condition prints when several marks are ticked. Used when the
--     unit is the player ("you"). The {{!positive|negated}} part is the wording for the condition
--     and for its NOT form.
-- %s #1: the unit phrase, e.g. "your target"
-- %s #2: the marks to match, comma separated, in the game's names, e.g. "Skull, Moon"
[4074] = "%s {{!다음 징표 중 하나 있음|다음 징표 중 하나 없음}}: %s",
-- ed95df2d English: %s {{!has|does not have}} one of these marks: %s
-- Context: Sentence the Raid Mark condition prints when several marks are ticked. Used when the
--     unit is anyone else (third person, "has"). The {{!positive|negated}} part is the wording for
--     the condition and for its NOT form.
-- %s #1: the unit phrase, e.g. "your target"
-- %s #2: the marks to match, comma separated, in the game's names, e.g. "Skull, Moon"
[4075] = "%s {{!다음 징표 중 하나 있음|다음 징표 중 하나 없음}}: %s",
-- c8ca4b13 English: %s {{!have|do not have}} the %s mark
-- Context: Sentence the Raid Mark condition prints when exactly one mark is ticked. Used when the
--     unit is the player ("you"). The {{!positive|negated}} part is the wording for the condition
--     and for its NOT form.
-- %s #1: the unit phrase, e.g. "your target"
-- %s #2: the game's name of the one mark, e.g. "Skull"
[4076] = "%s %s 징표 {{!있음|없음}}",
-- 8c22e3b7 English: %s {{!has|does not have}} the %s mark
-- Context: Sentence the Raid Mark condition prints when exactly one mark is ticked. Used when the
--     unit is anyone else (third person, "has"). The {{!positive|negated}} part is the wording for
--     the condition and for its NOT form.
-- %s #1: the unit phrase, e.g. "your target"
-- %s #2: the game's name of the one mark, e.g. "Skull"
[4077] = "%s %s 징표 {{!있음|없음}}",
-- 58d8289e English: the number of marked units
[4078] = "징표가 있는 유닛의 수",
-- e5568f80 English: the number of marked enemy units
[4079] = "징표가 있는 적대 유닛의 수",
-- 0112a03e English: the number of marked friendly units
[4080] = "징표가 있는 우호 유닛의 수",
-- e2490322 English: Marked units
-- Context: Choice in the Count dropdown of the Raid Mark Count condition: count every unit that
--     carries a marker.
[4081] = "징표가 있는 유닛",
-- cfc9ed3d English: Marked enemies
-- Context: Choice in the Count dropdown of the Raid Mark Count condition: count only marked units
--     the player can attack.
[4082] = "징표가 있는 적",
-- e9c0dcf1 English: Marked friendly units
-- Context: Choice in the Count dropdown of the Raid Mark Count condition: count only marked units
--     that are friendly.
[4083] = "징표가 있는 우호 유닛",
-- 205bd60c English: A number from 0 to 8: there are eight marks, and a unit carries at most one.
[4084] = "0에서 8까지의 숫자: 징표는 여덟 가지이며 유닛 하나는 최대 하나만 가집니다.",
-- 6bc4e7b1 English: Matches while the unit carries a raid target marker. Choose Any mark, No mark,
--     or One of these marks and tick the marks you want (skull, cross, square, moon, triangle,
--     diamond, circle, star). A unit that does not exist never matches, not even for No mark. Where
--     the game hides a marker (Retail and Forever restrict some data in combat) the condition is
--     unavailable, also under NOT, never false. To act on whichever unit carries a mark, pick the
--     mark itself as the Unit of another condition: Skull, Cross and the rest, or the
--     highest-priority marked unit, which tries skull first and star last.
[4085] = "유닛에 공격대 징표가 있는 동안 일치합니다. 아무 징표, 징표 없음, 이 징표 중 하나를 고르고, 원하는 징표를 선택하세요(해골, 가위, 네모, 달, 세모, 다이아몬드, 동그라미, 별). 존재하지 않는 유닛은 징표 없음에도 일치하지 않습니다. 게임이 징표를 숨기는 곳(리테일과 Forever는 전투 중 일부 데이터를 제한합니다)에서는 조건을 사용할 수 없으며, NOT에서도 마찬가지이고 거짓이 되지 않습니다. 징표가 있는 유닛에 대해 동작하려면 징표 자체를 다른 조건의 유닛으로 고르세요: 해골 등 각 징표, 또는 해골부터 별까지 차례로 확인하는 우선순위가 가장 높은 징표 유닛.",
-- 74adf719 English: Counts the marked units Rotation Master knows of. It finds them on your target,
--     focus, mouseover, nameplates, group members and their targets, bosses and arena opponents
--     each time a mark changes, so a marked unit you cannot reach right now still counts until the
--     mark is seen to be gone or you leave the area. Count every marked unit, only enemies, or only
--     friendly units. If a marker cannot be read, or a unit's hostility is unknown for the filter
--     you chose, the condition is unavailable, also under NOT. A unit carries at most one mark, so
--     the count is never more than eight.
[4086] = "Rotation Master가 알고 있는 징표 유닛을 셉니다. 징표가 바뀔 때마다 대상, 주시 대상, 마우스오버, 이름표, 파티원과 그 대상, 우두머리와 투기장 상대에서 유닛을 찾으므로, 지금 닿지 않는 징표 유닛도 징표가 사라진 것이 확인되거나 지역을 떠날 때까지 계속 셉니다. 징표가 있는 모든 유닛, 적만, 또는 우호 유닛만 셀 수 있습니다. 징표를 읽을 수 없거나 선택한 필터에 대해 유닛의 적대 여부를 알 수 없으면 조건을 사용할 수 없으며, NOT에서도 마찬가지입니다. 유닛은 징표를 최대 하나만 가지므로 개수는 8을 넘지 않습니다.",
}
